import { isThemeColorToken } from './../_shared/theme-color-token.js';

export function fromEntries(iterable: $TSFixMe) {
  return [...iterable].reduce((obj, [key, val]) => {
    obj[key] = val;
    return obj;
  }, {});
}

const isValidHexColor = (color?: string) =>
  color && /^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{8}|[A-Fa-f0-9]{3}|[A-Fa-f0-9]{4})$/.test(color);

export const getValidHexColor = (color?: string) =>
  color && isValidHexColor(color) ? color : undefined;

export const getValidColorValue = (color?: string) =>
  color && (isValidHexColor(color) || isThemeColorToken(color)) ? color : undefined;
